INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',332,'{"_type":"chat:Message","id":"-5124234082:2149","threadId":"telegram:-5124234082","text":"J’ai acheté :\n- un pot de tahini 230g\n- un tube de concentré de tomate 150g\nLe reste n’etait pas dispo. Ajoute le sur la liste continente","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"J’ai acheté :","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":14,"offset":13}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":14,"offset":13}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"un pot de tahini 230g","position":{"start":{"line":2,"column":3,"offset":16},"end":{"line":2,"column":24,"offset":37}}}],"position":{"start":{"line":2,"column":3,"offset":16},"end":{"line":2,"column":24,"offset":37}}}],"position":{"start":{"line":2,"column":1,"offset":14},"end":{"line":2,"column":24,"offset":37}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"un tube de concentré de tomate 150g\nLe reste n’etait pas dispo. Ajoute le sur la liste continente","position":{"start":{"line":3,"column":3,"offset":40},"end":{"line":4,"column":62,"offset":137}}}],"position":{"start":{"line":3,"column":3,"offset":40},"end":{"line":4,"column":62,"offset":137}}}],"position":{"start":{"line":3,"column":1,"offset":38},"end":{"line":4,"column":62,"offset":137}}}],"position":{"start":{"line":2,"column":1,"offset":14},"end":{"line":4,"column":62,"offset":137}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":62,"offset":137}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T09:13:34.000Z","ed